export const getRunWorkspaceCheckUrl = () => {




  return `/api/tools/run`
}

/**
 * @summary Run one allowlisted workspace check
 */
export const runWorkspaceCheck = async ( options?: RequestInit): Promise<SuccessResponseResponse> => {

  return customFetch<SuccessResponseResponse>(getRunWorkspaceCheckUrl(),
  {
    ...options,
    method: 'POST'


  }
);}




export const getRunWorkspaceCheckMutationOptions = <TError = ErrorType<ErrorResponseResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof runWorkspaceCheck>>, TError,void, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof runWorkspaceCheck>>, TError,void, TContext> => {

const mutationKey = ['runWorkspaceCheck'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof runWorkspaceCheck>>, void> = () => {


          return  runWorkspaceCheck(requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type RunWorkspaceCheckMutationResult = NonNullable<Awaited<ReturnType<typeof runWorkspaceCheck>>>

    export type RunWorkspaceCheckMutationError = ErrorType<ErrorResponseResponse>

    /**
 * @summary Run one allowlisted workspace check
 */
export const useRunWorkspaceCheck = <TError = ErrorType<ErrorResponseResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof runWorkspaceCheck>>, TError,void, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof runWorkspaceCheck>>,
        TError,
        void,
        TContext
      > => {
      return useMutation(getRunWorkspaceCheckMutationOptions(options));
    }

